INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(351800, 0, 3518, 0, 0, 8, 'Nagrand', 'Nagrand is one of the few green lands left on shattered Draenor. While the rest of the world was scorched by fel magic or torn apart, these rolling grasslands survived largely untouched, and great islands of earth still drift above the plains, spilling waterfalls into the lakes below. For the orcs, Oshu''gun, the diamond mountain in the southwest, was once the heart of their faith: the clans gathered beneath it each spring, and their shaman spoke there with the ancestors. Now the land is crowded with peoples and dangers. The Mag''har, orcs who never drank the demon''s blood, hold Garadar in the north, while the Kurenai, Broken draenei who seek redemption, have reclaimed Telaar in the south. Between them the abandoned draenei city of Halaa changes hands in open war. Warmaul and Boulderfist ogres fight over the hills, the Shadow Council lurks at Kil''sorrow Fortress, the Burning Legion builds forge camps in the west, and at the Throne of the Elements the Earthen Ring struggles to calm the restless spirits of the land.', 'warcraft.wiki.gg/wiki/Nagrand (sacred to the orcs, uncorrupted, last unscarred region, floating lake islands, Mag''har and Kurenai, Halaa contested); quest 10101 description (Oshu''gun, clans gathered, shaman communed with ancestors); quests 9890, 9946 (Boulderfist and Warmaul); quest 9935 (Kil''sorrow, communing with the Legion); quest 9999 (forge camps); quest 9804 (Earthen Ring, restless waters); warcraft.wiki.gg/wiki/Kurenai (redeemed Broken, Telaar); quest 9921 completion text (Telaar only recently taken back)'),
(351801, 1, 3518, 1, 0, 8, 'Garadar', 'Garadar, the home of the Mag''har, stands in northern Nagrand. Its people call themselves survivors of the red pox and of a shattered world, and because they were set apart from the rest of their race, they never shared the corruption that turned other orcs green. Today Garadar is a town under strain. Refugees from Sunspring Post and the Bleeding Hollow village crowd its streets with orphaned children, the matrons struggle to feed them, and the Greatmother lies ill in her hospice while young Garrosh broods by the fire. Captain Kroghan, a Horde officer sent only to pass through, has chosen to stay on as the Horde''s liaison to the town.', 'warcraft.wiki.gg/wiki/Garadar (red pox quarantine, named for Garad, Mag''har avoided corruption, Geyah''s hospice, Kroghan); creature_text 18489 (Grandson of Garad and Geyah); DB spawns in area 3613: Sunspring Post Refugee/Orphan, Bleeding Hollow Refugee/Orphan, Captain Kroghan 18090; quest 9916 description (burden on the matrons of Garadar); npc_text 9271 (Kurkush: Greatmother ill, Garrosh depressed); quest 9797 reward text (Kroghan); npc_text 9289 (Jorin: survivors of the Red Pox and of a shattered world); quest 11048 description (Kroghan stays as long term Horde liaison); warcraft.wiki.gg/wiki/Garad (Rise of the Horde has Garad killed by ogres; the quarantine and naming story cites Chronicle 2 and The Shattering)'),
(351802, 1, 3518, 2, 0, 8, 'Telaar', 'In the far south of Nagrand lies Telaar, one of the very few draenei towns on Draenor whose graceful architecture survived intact. It is home now to the Kurenai, a tribe of Broken who escaped their slavers and work to overcome their demonic taint; their name means redeemed. They took the town back only recently and mean to keep it. Arechron leads them, with Mo''mor the Breaker, Otonbu the Sage and Poli''lukluk the Wiser at his side. They have welcomed the Alliance their draenei kin have joined. In the town''s jail, blood elves captured at Halaa await questioning, and the old hatred between the Broken and the orcs is never far from anyone''s mind.', 'warcraft.wiki.gg/wiki/Telaar (intact draenei architecture, Kurenai town, Arechron); warcraft.wiki.gg/wiki/Kurenai (escaped slavers, overcoming taint, name means redeemed, support draenei joining the Alliance); quest 9921 completion text (only recently taken back Telaar); DB spawns area 3626: Mo''mor 18223, Otonbu 18222, Poli''lukluk 18224, Elementalist Ioki, Shotgun Jones, Consortium, Captured Halaani Blood Knight 19151, Interrogator Khan; npc_text 9738 (Telaari Jailor: blood elves questioned); quest 11502 description (history of bloodshed and betrayal with the orcs)'),
(351803, 1, 3518, 3, 0, 8, 'Halaa', 'On a plateau in the heart of Nagrand stand the empty halls of Halaa, once the foremost draenei research site for the study of naaru crystals. Its builders are long gone, but their notes on the crystals of Oshu''gun remain, and powder from the diamond mountain is found in the earth all across the region. That prize has drawn the Alliance and the Horde into open war. Draenei and blood elves fight over the town street by street, and whichever side holds it brings in researchers to gather the crystal powder, quartermasters to reward their soldiers, and guards to defend the walls until the next assault. Rarely does a banner fly over Halaa for long.', 'quest 10074/10076 description (primary draenei research facility for naaru crystals, Oshu''gun powder in the region); quest 9815 description (abandoned city of Halaa); warcraft.wiki.gg/wiki/Halaa (contested town, guards, researchers and quartermasters of the holding side); npc_text 9738 and 9739 (blood elves and draenei fighting at Halaa, after crystal powder); quest 9864 description (Halaa is a war-zone)'),
(351804, 1, 3518, 4, 0, 8, 'Halaani Basin and the Twin Clefts', 'Below the plateau of Halaa spreads the Halaani Basin, a wide hollow where Nagrand''s troubled waters gather. Spawns of muck crawl through its pools, and the Earthen Ring warns that each leaves tainted debris that will spread unless carried away. Enraged crushers, hulking elementals of living rock, roam the basin as well. Within it lie the twin clefts, Northwind and Southwind, where Boulderfist shock troops have hidden their ogre mounds. The ogres stacked supplies stolen from the Bleeding Hollow village in the clefts, and when young Corki of Telaar went looking for trouble, it was here that the Boulderfist caught and caged him.', 'quest 9815 description (muck spawns beneath Halaa, tainted debris); quest 9821 reward text (crusher rocks are poison); DB spawns 3666: Muck Spawn, Enraged Crusher; quests 9907, 9922 descriptions (twin clefts Northwind and Southwind, Boulderfist mounds); quest 9916 description (stolen supplies in the clefts); quest 9924 description and Corki 20812 at Northwind Cleft'),
(351805, 1, 3518, 5, 0, 8, 'The Throne of the Elements', 'In the northern hills beyond Skysong Lake rises the Throne of the Elements, a sacred place where the spirits of Nagrand are honored. The four furies dwell there in person: Gordawg of earth, Incineratus of fire, Aborius of water and Kalandrios of air. Shaman of the Earthen Ring keep the site, among them Elementalist Sharvak, who fears for a world whose people fight on while the elements themselves are in turmoil. Some of her companions are Broken, such as Morgh and Lo''ap, elementalists of the Ring like herself. Envoys of the Ring travel to both Garadar and Telaar to report on the state of the elements.', 'DB spawns 3615: Gordawg 18099 Fury of Earth, Incineratus 18100, Aborius 18101 Fury of Water, Kalandrios 18102, Elementalists Untrag, Sharvak, Lo''ap, Morgh; quests 9869, 9870 descriptions (northern hills beyond Skysong Lake, envoys to Telaar and Garadar); npc_text 9182 (Sharvak); quest 9862 description (Morgh: Murkblood are my kin); quest 9805 completion text (Lo''ap: my own kin); warcraft.wiki.gg/wiki/Throne_of_the_Elements (furies and Earthen Ring)'),
(351806, 1, 3518, 6, 0, 8, 'Skysong Lake', 'Skysong Lake lies just below the Throne of the Elements, and its waters are in turmoil. A disturbance in the ebb and flow of the region''s waters has driven the lake spirits into a frenzy, and they have begun to wreak havoc through the waterways. The shaman of the Throne say that Watoosun of the Water came to them in a vision and allowed them to put the maddened spirits down, on the condition that the cause of the trouble also be found. Talbuk graze along its shores, and the great crocolisk Goretooth hunts the lakes of Nagrand.', 'quest 9804 description (disturbance, agitated water spirits of Skysong Lake, Watoosun vision and condition); DB spawns 3614: Lake Spirit 17153, Talbuk Thorngrazer, Goretooth 17144 (rare, also spawns at Lake Sunspring and Halaani Basin); quest 9869 description (Throne beyond Skysong Lake); creature_template 17144 (family 6, crocolisk; rank 4 rare)'),
(351807, 1, 3518, 7, 0, 8, 'Windyreed Village', 'Windyreed Village, a cluster of huts southeast of the Throne of the Elements, is home to the Windyreed, a tribe of Lost Ones. The Lost Ones are draenei who have fallen even further than the Broken, a people once banished to the swamps of Zangarmarsh, and the scavengers and wretches who go about the huts bear every mark of that fall. They have come a long way from the marsh to settle here.', 'quest 9805 description and completion text (Lost Ones banished to Zangarmarsh, spread filth, kin dredging waters to create marsh, living fire of Incineratus, Windyreed Village southeast of the Throne); DB spawns 3634: Windyreed Scavenger 17139, Windyreed Wretch 17141, hut quest credits; warcraft.wiki.gg/wiki/Lost_ones (devolved further than the Broken; Windyreed tribe in Nagrand)'),
(351808, 1, 3518, 8, 0, 8, 'Sunspring Post', 'Sunspring Post was a Mag''har fishing village on the shore of Lake Sunspring, the only holding the orcs of Garadar kept outside their walls. It fell to a raid by the Murkblood, a tribe of Broken who serve the bog lord Musel''ek of Coilfang. The orcs who lived there were slain or driven out, and the Murkblood dumped the bodies into the lake, threatening the water that Telaar also drinks. Now Murkblood raiders and putrifiers prowl the empty huts, bending the spirits of the air to their will and troubling the lake with their magic as they search for something hidden there.', 'quest 9867 description (fishing village, kill or evict all orcs); quest 9863 description (only other territorial holding); quest 9862 description (Murkblood serve Musel''ek of Coilfang, sacked Sunspring, elemental magic); quest 9873 description (Musel''ek the bog lord); quest 9874 description (bodies dumped, primary source of water); quest 9862 completion text (searching for something); quest 9810 description (Watoosun''s Polluted Essence in Lake Sunspring)'),
(351809, 1, 3518, 9, 0, 8, 'The Ancestral Grounds', 'Far to the southwest of Garadar lie the Ancestral Grounds, where the Mag''har carry their dead to be laid among the honored spirits. It is the domain of Mother Kashur, a spirit of the ancestors who dwells there still. The grounds were always a quiet, undisturbed place, but of late the ancestral spirits have risen in great agitation, wandering the hills in torment. A funeral procession bound here from Garadar some days ago has not arrived.', 'quest 10081 description (Mother Kashur at the Ancestral Grounds, southwest); quest 10082 description (normally quiet and undisturbed, agitated spirits); DB spawns 3633: Agitated Orc Spirit 18043, Mother Kashur 18687; quests 9944, 9945 (funeral procession to the Ancestral Grounds ambushed by Warmaul, remains desecrated); quest 10101 (cause at Oshu''gun); quest 10081 (potion needed to speak with Kashur; a spirit is seen only if it allows it); warcraft.wiki.gg/wiki/Mother_Kashur (orc ghost)'),
(351810, 1, 3518, 10, 0, 8, 'Oshu''gun', 'Oshu''gun, the diamond mountain, towers over southwestern Nagrand, a vast crystal glittering above the plains. For the orcs it was the heart of their faith: every spring the clans gathered here for a great festival, and their shaman communed with the ancestors in its shadow, until the clans became a horde and the spirits fell silent. Its crystals draw covetous eyes. The Consortium wants to mine it, rogue ethereals are already prying fragments loose, and Shadow Council ritualists and Legion terrorguard have crept inside.', 'quest 10101 description (diamond mountain, springtime festival, shaman communed, clans became a horde, spirits silent); quest 10101 reward text (ship that first brought the draenei, K''ure); quest 9882 description (Consortium barred from Oshu''gun, Gava''xi''s rogue ethereals dislodging fragments); DB spawns 3630: Kil''sorrow Ritualist 18658, Terrorguard 18661, Vir''aani Raider/Arcanist; warcraft.wiki.gg/wiki/Oshu''gun (Kosh''harg, Shadow Council agents from Kil''sorrow)'),
(351811, 1, 3518, 11, 0, 8, 'The Spirit Fields', 'The Spirit Fields spread around the foot of Oshu''gun, and the name has never been more fitting. Ancient orc ancestors drift across the grass toward the mountain, murmuring of pain and a cold embrace, drawn by a pull they cannot resist. Voidspawn wander among them, and rogue ethereals of the Vir''aani pick at the mountain''s fallen crystals. The land is perilous in other ways. The gronn Durn the Hungerer circles the fields hunting anything that moves, and the great clefthoof Banthar leads her herd here.', 'DB spawns 3631: Ancient Orc Ancestor 18688, Voidspawn 17981, Vir''aani Arcanist/Raider, Gava''xi, Durn the Hungerer, Multiphase Disturbance; creature_text 18688 (ancestor lines); quest 10085 reward text (ancestors moving south); quest 10102 description (void minions drawn through the vortex); quest 9937 description (Durn lords over the Spirit Fields); quest 9851 (Banthar in the Field of Spirits); quest 11880 description (distortions in the Spirit Fields, Shattrath); creature 19475 Harbinger Haronem stands in Shattrath (quest 11880 giver)'),
(351812, 1, 3518, 12, 0, 8, 'Aeris Landing', 'North of Oshu''gun, the ethereal traders of the Consortium have set up camp at Aeris Landing. Their ground operations leader, Gezhe, spent months planning to mine Oshu''gun, which he calls the largest diamond known in the universe, only to be told by Nexus-Prince Haramad to wait until a political matter in Netherstorm was settled and not to anger the naaru. In the meantime Gezhe runs a clearing house for smuggled gems and pays well for ogre warbeads of obsidian. His security officer Zerid complains that the camp sits barely ten feet from crazed voidspawn, and the merchant Shadrek quietly buys elekk ivory, insisting it is not poaching.', 'npc_text 9287 (Gezhe: months of planning, largest known diamond in the universe, Haramaad, political matter in Netherstorm, clearing house for smuggled gems); quest 9882 description (might anger a naaru); quest 9913 description (Gezhe ground operations leader, Aeris Landing north of Oshu''gun); quest 9893 description (obsidian warbeads); quest 9925 description (Zerid, voidspawn ten feet away); quest 9914 description (Shadrek, not poaching)'),
(351813, 1, 3518, 13, 0, 8, 'Kil''sorrow Fortress', 'Kil''sorrow Fortress is a walled orc stronghold in southeastern Nagrand near the Terokkar border, named for the demon lord Kil''jaeden. Its masters, the Kil''sorrow, are agents of the Shadow Council who still commune with the Burning Legion. Cultists, spellbinders and deathsworn warriors patrol its walls alongside dark worgs, and its ritualists have spread to Oshu''gun. Garadar and Telaar both post bounties for Giselda the Crone and her lackeys, wanted for murder, ritual sacrifice, kidnapping, burglary and communing with the Legion.', 'warcraft.wiki.gg/wiki/Kil''sorrow_Fortress (agents of the Shadow Council, named for Kil''jaeden, near Terokkar border); quest 9935/9936 description (Giselda''s crimes, bounties at Garadar and Telaar); DB spawns 3637: Kil''sorrow Deathsworn, Cultist, Spellbinder, Dark Worg 18033, Giselda 18391; Kil''sorrow Ritualist at Oshu''gun; quests 9927, 9931 (Lantresor''s ruse); npc_text 9369 (Lantresor: Shadow Council attacks)'),
(351814, 1, 3518, 14, 0, 8, 'Burning Blade Ruins', 'East of Telaar, near the Terokkar border, the Burning Blade Ruins hold the largest gathering of Boulderfist ogres in southern Nagrand. Great pyres burn on the upper levels of the compound. From here the ogres have struck at their neighbors: Bleeding Hollow orcs were driven from their village in a night attack, and the Kurenai fear that the ogre hunting parties now ranging toward Telaar are the forerunners of an invasion.', 'quest 9921 description (largest collection of Boulderfist, east of Telaar near Terokkar); quest 9910 description (flaming pyres on upper levels, Mag''har battle standards); quests 10107/10108 (Lantresor on an upper platform, blademaster); quest 9890 description (Warmaul pushing Boulderfist); quest 9888 description (attack on Jorin''s village); quest 9921 description (precursor to invasion of Telaar); quest 9923/9924 (Corki rescued from the Burning Blade Ruins); DB spawns 3610'),
(351815, 1, 3518, 15, 0, 8, 'Laughing Skull Ruins', 'Against the northern mountains of Nagrand lie the Laughing Skull Ruins, one of the old villages of the orc ancestors. The Warmaul ogres have overrun it and built an ogre mound among its broken walls. From here Zorbo the Advisor and his reavers and shaman have planned attack after attack on Garadar and Telaar, slaying orcs and Broken alike, and both towns pay for proof of his death. A blazing pyre lights the ruins'' courtyard. The most famous corner of the ruins, though, is the Ring of Blood, where the goblin Gurgthock stages fights for the ogres'' amusement.', 'quests 9939/9940 descriptions (Zorbo, reavers and shaman, Laughing Skull Ruins in the northern mountains, attacks on Garadar and Telaar); quest 10085 description (Laughing Skull Ruins among the villages of the ancestors); warcraft.wiki.gg/wiki/Laughing_Skull_Ruins (overrun by Warmaul, ogre mound, Ring of Blood); quest 9932 description (pyre in the courtyard, bodies); npc_text 9735 (Gurgthock runs the Ring of Blood at the old Laughing Skull Ruins)'),
(351816, 1, 3518, 16, 0, 8, 'Warmaul Hill', 'In the northwestern mountains of Nagrand stands Warmaul Hill, stronghold of the Warmaul ogres. Its great cave once belonged to the gronn who ruled these ogres, until Cho''war the Pillager drove them out and named himself king. The Warmaul are cruel even by ogre standards. They keep captured Mag''har in cages to be eaten fresh, their chef stirs a bubbling stew and boasts of his Broken chowder, and they hoard supplies stolen from a Kurenai caravan. Mountain gronn still roam the slopes.', 'quest 9946 description (Cho''war forced the gronn out of the cave, declared himself king); quest 9948 description (prisoners kept alive for food); creature_text 18440 (Warmaul Chef Bufferlo: stew, Broken chowder); quest 9956 description (caravan supplies stolen); quest 9853 description (ogre worships Gurok, earthen brand at Warmaul Hill); DB spawns 3617: Mag''har Prisoner, Warmaul Prison, Mountain Gronn 19201, Telaar Supply Crate'),
(351817, 1, 3518, 17, 0, 8, 'The Forge Camps', 'In the far west of Nagrand the Burning Legion has raised two forge camps, Hate and Fear, to build weapons for its war on this land. Each camp has a forge, spell warding towers and a transporter linking it to the Legion''s armies, and as long as the transporters stand nothing done to the camps will last. Mo''arg engineers and tinkerers labor beneath the watch of felguard and the fel cannons of the camp defenses. A mo''arg master planner keeps the blueprints that decide where every structure goes, and each camp is ruled by a pit lord overseer, Demos at Hate and Xirkos at Fear, so dangerous that Altruis warns any who would face them to bring allies.', 'npc_text 9427 (Altruis: two forge camps, transporter, forge, warding towers, fel cannons, pit lord overseers); quest 9999 description (transporters, engineers and tinkerers); quest 10001 description (master planner and blueprints); DB spawns 3624/3625: Demos, Overseer of Hate 18535; Xirkos, Overseer of Fear 18536; Mo''arg Master Planner; Gan''arg Tinkerer; Mo''arg Engineer; Felguard Legionnaire; Legion Fel Cannon; warcraft.wiki.gg/wiki/Altruis_the_Sufferer (weapons in western Nagrand)'),
(351818, 1, 3518, 18, 0, 8, 'Nesingwary Safari', 'On the northeastern edge of Nagrand, near the border of Zangarmarsh, the famous dwarf hunter Hemet Nesingwary has pitched his camp. He came to Outland in search of real big game, and he has the scars to prove he found it. With him are Shado Farstrider, a quiet hunter who earned the nickname Fitz by losing a wager to Hemet over a frostsaber in Winterspring, and Harold Lane, who insists that the infected scratch he got brawling with a talbuk stag and a pair of windrocs is nothing. Their pilot, Marsha, is patching up the flying machine that crashed because Hemet shot through its ailerons. A copy of Hemet''s book, The Green Hills of Stranglethorn, lies in the camp.', 'quest 10113 log description (outskirts of northeast Nagrand, towards Zangarmarsh); npc_text 9221 (Hemet: prey in Outland the real deal, scars); npc_text 9283 (Fitz: Winterspring, Rak''shiri wager, nickname); npc_text 9258 (Harold Lane scratch); npc_text 9290 (Pilot Marsha, ailerons); gameobject 182203 The Green Hills of Stranglethorn in area 3673; quest 10114 description (expedition came from Azeroth)'),
(351819, 1, 3518, 19, 0, 8, 'The Ring of Trials', 'The Ring of Trials is the great arena of Nagrand, and the old battlemaster Garokk remembers when it was a place of great glory and honor. Then the Steamwheedle Cartel arrived with wagons of gold and pens sharper than any axe. The goblins took the arena over and renamed it Steamwheedle Stadium, and it now hosts the bouts of the Steamwheedle Fighting Circuit. The organizer King Dond sells the charters that would-be gladiators need, while the brute Ear-Biter turns away anyone he judges unworthy of the ring. Garokk lingers nearby, a battlemaster without a battle.', 'npc_text 9637 (Garokk: once a place of great glory and honor, Steamwheedle came with gold and quill pens); creature_text 18897 (recently appropriated and callously renamed Steamwheedle Stadium); npc_text 10608 (King Dond sells arena team charters, Steamwheedle Fighting Circuit); npc_text 10214/10215 (Ear-Biter); creature_template 18439 subname Ex-Arena Battlemaster; warcraft.wiki.gg/wiki/Nagrand (Ring of Trials, the zone''s arena)'),
(351820, 1, 3518, 20, 0, 8, 'The Twilight Ridge', 'High on the Twilight Ridge of western Nagrand, reached only on wings, stands a dimensional gateway through which the Burning Legion once brought demons into this world. The gateway is dark now, but not forgotten. Deathshadow cultists have built a camp around it, and Shadow Council spellcasters channel magic into its frame in an effort to stabilize it and open the way again. They are overseen by the eredar Reth''hedron the Subduer, whose own brother, Balthas, is a lord in Illidan''s service. Illidan''s forces strike at the ridge whenever they can, determined that the portal stay closed.', 'warcraft.wiki.gg/wiki/Twilight_Ridge (Legion dimensional gateway no longer functional, Deathshadow cultists, Reth''hedron, Shadow Council channeling into the frame, flying only); quest 11086 description (demons attempt to stabilize the portal on the Twilight Ridge; Dragonmaw silencing those who defy Illidan); quest 11090 description (Reth''hedron, brother of Illidari Lord Balthas); DB spawns 3764: Deathshadow Spellbinder/Warlock/Archon/Acolyte/Overlord, Reth''hedron the Subduer 22357'),
(351821, 1, 3518, 21, 0, 8, 'The Abandoned Armory', 'North of Telaar stands the Abandoned Armory, an old draenei building where Boulderfist ogres now stack stolen Bleeding Hollow supplies, and Boulderfist mages and warriors keep watch over the crates. One resident is not an ogre. The draenei Nitrin the Learned lives here among the ruins, a scholar who keeps his own counsel and has nothing to say to passing strangers.', 'DB spawns 3839: Nitrin the Learned 19844, Boulderfist Mage/Warrior, Bleeding Hollow Supply Crate; quest 10251 description (old Abandoned Armory, north of Telaar); creature_template 19844 Nitrin the Learned (npcflag 2, no gossip menu); data/lore/terokkar.json 351940 The Book of the Dead (tells the Levixus story)'),
(351822, 2, 3518, 1, 2, 8, 'Greatmother Geyah', 'Greatmother Geyah is the venerable matriarch and spiritual leader of the Mag''har. In a very real sense she raised every orc in Garadar: most were too young or too sick to remember the Dark Portal, many of them orphans, kept apart from the healthy as Blackhand willed, and she nursed them back to health. The town''s matrons dread the day she passes. That day seems close: she has fallen gravely ill and keeps to the hospice, while the clan''s young war chief sinks into despair, calling her the balance that holds back his father''s blood lust. Yet her mind is sharp, and she still guides those who would help her people.', 'warcraft.wiki.gg/wiki/Garadar (spiritual leader, Durotan''s mother, hospice); npc_text 9297 (Matron Drakia: the Greatmother raised all of us); quest 9944 description (Greatmother taken ill); quest 9868 reward text (Greatmother is dying); npc_text 9508, 9509 (gossip during 10044: orphans, keep the sick from the healthy, nursed them back to health, Garrosh says I am his balance)'),
(351823, 2, 3518, 2, 2, 8, 'Garrosh', 'Garrosh, son of Grommash Hellscream, is the young war chief of the Mag''har and heir to lead them when the Greatmother passes. He carries that duty like a curse. He has grown up in the shadow of his father''s name, for the blood lust that consumed Grom Hellscream is said to have cursed their people, and Garrosh fears the same rage waits in his own veins. With Geyah dying and enemies on every side, he sits by the fire in Garadar, unmoved by victories and deaf to calls for action, while Jorin Deadeye openly calls him an impotent whelp.', 'creature_template 18063 subname Son of Hellscream; warcraft.wiki.gg/wiki/Mag''har (military chief, to succeed Geyah); quests 9868, 9872, 9934 reward texts (depressed, dismissive); quest 9891 reward text (Jorin: impotent whelp); npc_text 9509, 9510 (Geyah: the blood lust that consumed his father and cursed our people; he fears his rage will consume him); npc_text 9271 (Kurkush: not his father''s boy)'),
(351824, 2, 3518, 3, 2, 8, 'Jorin Deadeye', 'Jorin Deadeye, son of Kilrogg, calls himself the last of the line of Deadeye, warchiefs of the Bleeding Hollow clan, and he names the Mag''har proudly as survivors: of a fallen dynasty, of the red pox and of a shattered world. When Boulderfist ogres fell on his village by night and drove his people out, he escaped to Garadar and found its leader weeping into a fire. Jorin has little patience for that. He believes ogres respect only might, and he sends every willing warrior to teach them so.', 'npc_text 9289 (son of Kilrogg, last of the lineage of Deadeye, survivors); quest 9888 description (village attacked at night, Garrosh weeping into a fire); quest 9906 description (ogres moved by might); quest 10107 description (Diplomatic Measures); warcraft.wiki.gg/wiki/Garadar (aide to Garrosh)'),
(351825, 2, 3518, 4, 2, 8, 'Saurfang the Younger', 'Saurfang the Younger was one of the Garadar younglings who could bear no more after yet another Murkblood raid and set out to strike back, though their elders tried to stop them. The war party, barely grown, took the western road toward Sunspring Post and was cut to pieces. Alone left alive, he tells of a rage that burned through his whole being as thirty Murkblood closed around him, and of waking later with no memory of the fight, eyes still flashing red. Nearly dead, he was found by the survivors of a funeral procession, and now he burns for vengeance.', 'quest 9864 description (younglings, rage, western road); npc_text 9275 (the rage, thirty Murkblood, blacked out, eyes glow red); quest 9944 reward text (found nearly dead near Sunspring); quest 9865 description (I seek vengeance, blood for blood)'),
(351826, 2, 3518, 5, 1, 8, 'Arechron', 'Arechron leads the Kurenai of Telaar, and he carries the weight of his people with a weary dignity. Murkblood raiders and Boulderfist ogres press on a town the Kurenai have only recently taken back. His greatest trial, though, is his son Corki, a boy whose curiosity keeps leading him into trouble. Even from inside an ogre cage, Corki assures his rescuers that his father, the leader of Telaar, will reward them handsomely, and Arechron can only sigh that the boy will be the death of him.', 'warcraft.wiki.gg/wiki/Kurenai (main leader Arechron); quest 9923 description (my father will reward you handsomely, the leader of Telaar); quest 9921 completion text (only recently taken back Telaar); quest 9917 description (first Murkbloods and now ogres)'),
(351827, 2, 3518, 6, 0, 8, 'Lantresor of the Blade', 'Lantresor of the Blade is an old orc blademaster who makes his home on a high platform of the Burning Blade Ruins, in the midst of the Boulderfist ogres. To a stranger''s eye he looks every inch an orc. He greets those who come before him by asking who so boldly stands there and whether they do not know death by sight, and he is as cunning as he is deadly.', 'quests 10107/10108 descriptions (ancient orc who passed through the Dark Portal in the time of our fathers, returned, blademaster, upper platform); npc_text 9361 (do you not know death by sight); warcraft.wiki.gg/wiki/Lantresor_of_the_Blade'),
(351828, 2, 3518, 7, 0, 8, 'Altruis the Sufferer', 'Altruis the Sufferer is a night elf demon hunter who came to Outland in Illidan''s service and left it. He still honors Illidan for setting him on his path, but believes his old master has become the very thing he swore to fight, and he counts the Illidari as foul as any demon. He rode into Nagrand on Nethrandamus, his nether drake, asked questions in Garadar and Telaar and let it be known that seekers of a purpose would find one with him. His camp in the west looks out over the Legion''s forge camps. His name is feared in the Legion''s fields, and the Aldor and the Scryers send their agents to him for knowledge of Illidan''s demon hunters.', 'quest 10668 description (respect for Illidan, corrupted, Illidari an abomination); quests 9982/9983 descriptions (arrived on a nether drake, asked questions, seek a purpose); quest 9991 description (Nethrandamus); npc_text 9419 (what do you see when you look to the west); quests 10640/10689 descriptions (name feared in the Legion fields of Nagrand, Aldor and Scryers); warcraft.wiki.gg/wiki/Altruis_the_Sufferer (night elf, brought to Outland by Illidan, defected)'),
(351829, 2, 3518, 8, 0, 8, 'K''ure', 'Deep within Oshu''gun dwells K''ure, a naaru whose voice is a gentle melody in the mind. The Consortium has been ordered to stay out of the mountain for fear of angering a powerful naaru, and Gezhe''s people grumble that they must wait while the Sha''tar finish whatever business they have inside. Around the mountain, orc ancestors drift toward Oshu''gun as if something within were calling them.', 'DB spawn: K''ure 17545 in area 3631 by Oshu''gun; quest 10101 reward text (a gentle, melodic voice fills your mind); quest 9882 description (might anger a certain powerful naaru); quest 9893 reward text (wait for the Sha''tar inside Oshu''gun); creature_text 18688 (ancestors: it draws me in)'),
(351830, 2, 3518, 9, 0, 8, 'Cho''war the Pillager', 'Cho''war the Pillager holds the deepest caves of Warmaul Hill, in the northwestern mountains of Nagrand, and the Warmaul ogres of the hill answer to him. The way to him runs past cages of captives, heaps of stolen goods and a great many of his warriors, for he is never left unguarded, and those who reach him find a huge and brutal ogre ready to fight for his cave.', 'quest 9946 completion text (heavily guarded); DB spawn 18423 at Warmaul Hill; DB spawns at Warmaul Hill: Mag''har Prisoner, Warmaul Prison, Telaar Supply Crate; creature_template 18423 (no subname)'),
(351831, 2, 3518, 10, 0, 8, 'Durn the Hungerer', 'Durn the Hungerer is a gronn, one of the sons of Gruul, the great gronn lord whose lair lies in the Blade''s Edge Mountains. Durn has claimed the Spirit Fields around Oshu''gun as his hunting ground. He circles the mountain without rest, destroying everything in his path. He is huge and merciless even by the measure of his kind, and anyone who crosses the fields near the diamond mountain may find the gronn bearing down on them.', 'creature_template 18411 subname Son of Gruul; warcraft.wiki.gg/wiki/Durn_the_Hungerer (one of the seven sons of Gruul, circles the Spirit Fields); quests 9937/9938 descriptions (lords over the area around Oshu''gun, decimating all, none able to rid Nagrand of him, gather allies); warcraft.wiki.gg/wiki/Gruul (Gruul''s Lair in Blade''s Edge, ogre overlord)'),
(351832, 3, 3518, 1, 0, 8, 'The Fall of Sunspring Post', 'When the Murkblood Broken sacked Sunspring Post, slaying or driving out every orc who lived there, both of Nagrand''s towns felt the blow. In Garadar, the farseers of the Lightning Sons refuse to sit idle while their chieftain grieves: one seeks the Murkblood''s twisted idols, another their leader''s head. In Telaar, the Kurenai fear for the lake. Otonbu the Sage wants the rotting bodies of the dead burned before they poison the water, knowing the orcs will never understand, and Poli''lukluk sends fighters to thin the raiders, for all an orc sees is Broken. At the Throne of the Elements, the Earthen Ring has learned that the raiders are capturing spirits of the air.', 'quests 9863, 9867 (Lightning Sons farseers, idols, leader''s head on a pike); quests 9874 description and reward text (Otonbu, corpses, peace set back); quest 9878 description (Poli''lukluk, all an orc sees is Broken); quest 9862 (Morgh, putrifiers capture air spirits); creature_template 18066 subname The Lightning Sons'),
(351833, 3, 3518, 2, 2, 8, 'The Missing Procession', 'Though the Greatmother lies ill, she insists that life must go on, that her people must serve as an example to Garrosh, and so a funeral procession of Mag''har set out from Garadar for the Ancestral Grounds. Funeral rites are sacred to the Mag''har. Several days later the procession has still not returned. Matron Drakia, with so many other matters to attend to, asks a stranger to follow the western road out of Garadar, keep clear of Halaa, and search for the missing mourners.', 'creature_queststarter: 9944 from Matron Drakia 18302; quest 9944 description (Greatmother says life goes on, an example for Garrosh, procession to the Ancestral Grounds, western road, avoid Halaa); quest 9946 reward text (sacred Mag''hari rituals)'),
(351834, 3, 3518, 3, 0, 8, 'Lantresor''s Gambit', 'The Boulderfist ogres are on the move. In Garadar, Jorin Deadeye, driven from his village in a night attack, sends help to his scout Kilrath, who hides by the ruined Bleeding Hollow village over the Terokkar border watching the ogres and their fat leader. In Telaar, the huntress Bintook spots an ogre hunting party far from its mound, and the Kurenai fear it is the first sign of an invasion. Both towns mean to answer with blood at the Burning Blade Ruins and the twin clefts of the Halaani Basin, but neither yet knows who leads the Boulderfist, or why they have come south.', 'quest 9888 description (night attack, Kilrath hides on the border); quest 9917 description (ogre hunting party far from its mound); quest 9921 description (precursor to invasion)'),
(351835, 3, 3518, 4, 0, 8, 'Gurok the Usurper', 'At the Throne of the Elements, Elementalist Untrag feels something pounding beneath the earth, endlessly, as if to punish it, and sends a stranger to hear the earth fury Gordawg. Gordawg speaks little. He chews rocks to learn where they have been, and he knows that something from the underneath is forcing the elements out. First he sets the stranger to lay the tortured earth spirits of the Telaari Basin back to sleep, then to break the raging crushers that roam Nagrand and bring him their pieces to taste.', 'quest 9818 description (Untrag, beating underneath, listen to Gordawg); quest 9819 description (tortured earth spirits, Telaari Basin); quest 9821 description (break them, bring Gordawg the pieces)'),
(351836, 3, 3518, 5, 0, 8, 'The Polluted Waters', 'Elementalist Lo''ap of the Earthen Ring can see that Nagrand''s waters are sick. Before sending anyone into them, he prepares tablets from a rare bean, picked from the dung of the plains'' beasts, that let a body breathe water as if it were air. The maddened water spirits of Skysong Lake must be put down first, with the permission of Watoosun of the Water, who has granted it on one condition: that the source of the disturbance be found as well. Beneath Halaa, meanwhile, spawns of muck must be slain and their tainted cores carried away so that the poison spreads no further.', 'quest 9800 description and reward text (caracoli bean from dung, tablet to breathe water); quest 9804 description (Skysong lake spirits, Watoosun''s permission); quest 9815 description (muck spawns in Halaani Basin, cores)'),
(351837, 3, 3518, 6, 0, 8, 'The Ring of Blood', 'In the Laughing Skull Ruins the Warmaul ogres keep a fighting pit, the Ring of Blood, and the goblin Gurgthock runs its bouts, with his troll servant Wodin at hand. The rules are simple: the fight ends when one side lies dead on the arena floor. A challenger''s first opponent is Brokentoe, a ferocious clefthoof, and from there the fights only grow harder, on the road to a bout with the Warmaul champion. Mogor, hero of the Warmaul, watches every fight and scoffs at the winners while the ogres'' bets climb. Gurgthock, of course, bets on the challenger.', 'npc_text 9735 (Gurgthock runs the show at the old Laughing Skull Ruins); quest_template 9962 ender Wodin the Troll-Servant 22893; quest 9962 description (Brokentoe, face down on the arena floor); npc_text 9394 (Gurgthock: become the Warmaul champion); creature_text 18069 (Mogor scoffs after each bout); quest 9970 reward text (Gurgthock betting the bank on you)'),
(351838, 3, 3518, 7, 0, 8, 'Altruis and the Forge Camps', 'When Altruis the Sufferer arrived in western Nagrand, he left word in Garadar and Telaar that any who sought a purpose should come to him. He is a hunter of demons, and once he could sense a demon from a thousand paces, but the Legion has put wards around its forge camps to the west that hide them from his sight. So he sends his volunteers soaring over the camps on the back of his nether drake, Nethrandamus, to note every structure and every defense, so that a counterattack can be planned.', 'quests 9982/9983 descriptions; quest 9991 description (catalog the camps on Nethrandamus); npc_text 9421, 9422 (Altruis: a demon from a thousand paces; wards to prevent detection)'),
(351839, 3, 3518, 8, 2, 8, 'The Restless Ancestors', 'Sent for by the Greatmother through a grudging Garrosh, a stranger comes before Greatmother Geyah. Mother Kashur, a spirit of the Ancestral Grounds, wishes to speak with them, and to make that possible Geyah sends the stranger across Outland for four herbs: Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade''s Edge Mountains. From them she brews a potion meant to expand the mind, so that the stranger may see the spirits and speak with them.', 'quest 10044 description (Garrosh delivers the summons); quest 10045 description (four herbs from four lands, potion)'),
(351840, 3, 3518, 9, 2, 8, 'Hero of the Mag''har', 'The ancestors can rest at last, and the Greatmother hopes the news will lift even the young Hellscream from his malaise. Garrosh, son of Grom, has sat by the fire through every victory won for the Mag''har, sure that his cursed blood makes him unfit to lead. So Geyah sends the stranger who has done so much for her people to Garrosh himself, to tell him of their latest victory and to say that all of it was done for him and for his people.', 'quest 10170 description (perhaps even the young Hellscream will be lifted from his malaise); quest 10171 description (tell him you do what you do for him and his people)'),
(351841, 3, 3518, 10, 0, 8, 'The Nagrand Safari', 'Hemet Nesingwary does not let just anyone hunt with his expedition, and in Nagrand the tests are harder than ever. Hemet starts his recruits on the clefthoof near camp, then the far more dangerous bulls, and finally Banthar, the fiercest and hairiest clefthoof in Outland, who roams with her herd near Oshu''gun. Fitz Farstrider, who speaks of honoring the last heartbeats of fallen prey, leads hunters through ever deadlier windrocs to their mother, Gutripper, far to the west. Harold Lane, too sick from his scratch to hunt, sends others after talbuk stags, thorngrazers and Bach''lor, king of the stags.', 'quests 9789, 9850, 9851 (clefthoof, bulls, Banthar fiercest and hairiest, Field of Spirits near Oshu''gun); quests 9854, 9855, 9856 (Fitz, last heartbeats, Gutripper mother of windrocs, far west); quests 9857, 9858, 9859 (Harold Lane, stags, thorngrazers, Bach''lor king of the stags)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(351805, 1, 0, 255, 'The Broken who serve at the Throne carry a private shame. Among those who corrupt the land and torment its elements are their own kin, other fallen draenei, and the shaman do not hide their grief when they admit it.', 'quest 9805 completion text (Lo''ap: with great shame, my own kin); quest 9862 description (Morgh: Murkblood are my kin)'),
(351807, 1, 0, 255, 'The shaman of the Throne name the village as one source of the sickness in Nagrand''s waters. The Lost Ones, they say, mean to carry their corruption out of the marshes and into these lands, and the Earthen Ring has sought the counsel of the furies on how to answer them.', 'quest 9805 description (Lost Ones spreading their filth, the wisdom of the furies, to stop the source)'),
(351807, 2, 0, 255, 'The furies answered with fire. Flame drawn from Incineratus himself was set loose among the huts to show the Lost Ones the wrath of the elements, and it checked the spread of their pollution, though other troubles soon surfaced. Lo''ap, ashamed, owned that the villagers were his own kin, dredging up Nagrand''s waters to make marsh.', 'quest 9805 description, completion and reward text (living fire of Incineratus on the huts, my own kin, create marshland, stifled the spread, other troubles surfaced)'),
(351808, 1, 0, 255, 'Something worse lurks in the depths of the lake. When Watoosun of the Water shed the stink of corruption, the filth took on a life of its own: a polluted spirit made of the vilest stuff found among the elements, which now hides in Lake Sunspring and breeds corrupt offspring.', 'quest 9810 description (Watoosun shed the corruption, twisted spirit essence, depths of Lake Sunspring, corrupt offspring)'),
(351809, 1, 0, 255, 'The procession will never arrive. On the road from Garadar the Warmaul surrounded it, cut down its guards and most of its mourners, and defiled the body of the elder being carried to rest, for no reason but to show what they could do.', 'quest 9945 description (ambushed by Warmaul from all sides, desecrated remains of the elder, display their power)'),
(351809, 2, 0, 255, 'What troubles the spirits does not lie in these grounds. The ancestors have left every one of their old villages and are drifting south, drawn toward Oshu''gun, and it is there, in the shadow of the diamond mountain, that Mother Kashur seeks the cause.', 'quest 10085 reward text (none of the ancestors at their villages, all moving south); quest 10101 description (something draws them from their rest, venture to Oshu''gun)'),
(351810, 1, 0, 255, 'The mountain is not stone at all. It is the wreck of the vessel that first carried the draenei across the stars, which came down out of the sky and crashed here in an age long past, and within it, trapped in the wreckage, lingers the naaru K''ure, whose weakened energies have never escaped.', 'quest 10101 reward text (K''ure of the naaru, ancient vessel, ship that first brought the draenei, crashed many hundreds of years ago, energies trapped)'),
(351811, 1, 12, 255, 'Of late, strange dark distortions have begun to appear in the air over the Spirit Fields. They cannot be seen with the naked eye, but a gnomish inventor insists that readings from them are vital to the campaign at the Sunwell, and volunteers are sent out from Shattrath with special goggles to take them.', 'quest 11880 description (a gnomish inventor babbling about dark distortions in the Spirit Fields, goggles to see them, our campaign at the Sunwell); DB spawns: Multiphase Disturbance 25882 in area 3631; creature 19475 Harbinger Haronem stands in Shattrath (quest 11880 giver); mod-individual-progression ipp_aware_npcs.sql (Haronem 19475 phaseMask 65536) and checkIPPhasing (Shattrath gets that phase once TBC tier 4, state 12, is reached)'),
(351813, 1, 0, 255, 'Of late the fortress has found a new enemy. Warmaul banners turned up driven through the hearts of slain Kil''sorrow, and the bodies of Kil''sorrow soldiers were laid out in the Laughing Skull Ruins as if after a great battle, until the Kil''sorrow and the Warmaul ogres were at war. It was all a ruse by Lantresor of the Blade.', 'quests 9927, 9931, 9932 (banners, bodies, smoke signal); quests 9933, 9934 descriptions (offered once the ruse is done)'),
(351814, 1, 0, 255, 'The Boulderfist did not come here by choice. A new clan of ogres, the Warmaul, has taken their lands to the north and is driving them ever further south, and the Boulderfist have turned in desperation on the orcs and Broken in their path.', 'quest 9890 description (Warmaul took most of our land, we are being exterminated, no choice but to take this town), told to Jorin on DONE 9891; npc_text 9354 (Lump, during 9918: Warmaul tribe kick Boulderfist out of mound to north); quest 9920 reward text (new tribe forcing the Boulderfist south)'),
(351814, 2, 0, 255, 'The Mag''har answered in kind. Warriors of Garadar fought their way through the compound and planted Mag''har battle standards beside the three great pyres on its upper levels, a lasting reminder for any ogre who missed the battle.', 'quest 9910 description and completion text (standards at the three Burning Blade pyres, lasting impression, respect from fear)'),
(351814, 3, 0, 255, 'Arechron''s son Corki once wandered in here and ended up in an ogre cage, crying that the Boulderfist were going to eat him and that his father would pay handsomely for his rescue. A stranger took the key from one of the ogres and freed him, and the boy''s father could only shake his head.', 'quest 9923 description, completion and reward text (key on one of the ogres, my father will reward you, he''ll be the death of me)'),
(351814, 4, 0, 255, 'The Boulderfist have an unlikely master. Word reached both towns that the ogres answer to an orc, an aged blademaster who went through the Dark Portal a generation ago and has returned to Draenor, and who keeps to an upper platform of these very ruins.', 'quests 10107/10108 descriptions (the Boulderfist leader is an orc, ancient, passed through the Dark Portal, upper platform, blademaster)'),
(351815, 1, 0, 255, 'The courtyard pyre once served a darker purpose. At a smoke signal sent up beside it, Boulderfist ogres crept in and laid out the bodies of slain Kil''sorrow orcs around the fire, so that the Warmaul would believe a great battle had been fought there and turn on the Kil''sorrow.', 'quest 9932 description and texts (pyre in the Laughing Skull Courtyard, smoke signals, ogres plant the bodies of slain Kil''sorrow, final straw)'),
(351816, 1, 0, 255, 'The hill hides a darker secret. Somewhere on its slopes the ogres worship Gurok, an earth spirit who betrayed the elements, at an earthen brand of stone, and Gordawg of the Throne of the Elements says that seven Warmaul skulls laid upon it will call the usurper out.', 'quest 9853 description (find where ogre worships Gurok at Warmaul Hill, earthen brand, seven skulls); quest 9849 reward text (Gurok betrayed the elements)'),
(351822, 1, 0, 255, 'Geyah is the mother of Durotan, the Frostwolf chieftain who left Draenor long ago with his mate Draka and gave his life so that later generations might be born free of the blood curse. Draka was carrying a child when they left, and Geyah secretly begged the spirits to protect it. When word came that Durotan''s son had survived and now leads the Horde, she wept, and begged to see her grandchild before she leaves this world.', 'npc_text 9822, 9823, 9824, 9825 (gossip while 10172 is taken: my son, Durotan, sacrificed himself, without the blood curse; the child Draka told me of; I must see my grandchild); gossip_menu_option 7977/7978 (the warchief is the son of Durotan); quest 10175 description (go to my grandchild); warcraft.wiki.gg/wiki/Durotan (Frostwolf chieftain)'),
(351822, 2, 0, 255, 'Her grandson came. Thrall, Warchief of the Horde, walked into Garadar bearing the Doomhammer, and Geyah knew him at once by his father''s broad shoulders and his mother''s fierce eyes. She gave him the name Durotan had chosen for his unborn son, Go''el, and the people of Garadar bowed their heads to the grandson of Garad and Geyah.', 'creature_text 18141 (broad shoulders, fierce eyes, Go''el, Doomhammer); creature_text 18489 (Grandson of Garad and Geyah, bow your heads); smart_scripts 18141 (the Thrall event runs on the 10212 turn-in)'),
(351823, 1, 0, 255, 'Even the news that the ancestors could rest did not move him. His people were proud, he granted, proud to see one more winter, but he could see nothing beyond it. The stranger should lead the clan, he said, so that he could die when the Greatmother passed and be free of his family''s shame. His cursed blood ran too deep; he would not be the second Hellscream to bring ruin on the orcs.', 'quest 10171 reward text (another winter, maybe you should lead this clan, allowed to die); quest 10172 description (second Hellscream to damn the orcs)'),
(351823, 2, 0, 255, 'It was Thrall who freed him. At the Greatmother''s request the Warchief told Garrosh the truth of how his father died, and Garrosh, who had hated Grom for the burden he left, found redemption in it. Before all of Garadar he proclaimed himself Garrosh Hellscream, son of Grom and chieftain of the Mag''har.', 'creature_text 18141 (will you tell Garrosh about his father); creature_text 18063 (I hated him for the burden, redemption, Garrosh Hellscream son of Grom, chieftain of the Mag''har)'),
(351823, 3, 13, 255, 'The chieftain of the Mag''har was not to remain a stranger to the wider Horde. When the Horde went to war against the Lich King, Garrosh Hellscream was named Overlord of the Warsong Offensive, and at Warsong Hold, its foothold in the Borean Tundra, the soldiers say it is through the leadership of the son of Hellscream that they will reach Icecrown.', 'creature_template 25237 Garrosh Hellscream, subname Overlord of the Warsong Offensive, spawned on map 571 at Warsong Hold (area 4129); quest 11585 description (foothold in Northrend, journey to Icecrown, through the leadership of the son of Hellscream we will succeed)'),
(351824, 1, 0, 255, 'Yet he is shrewd as well as fierce. When his scout sent word that the Boulderfist answered to one of their own race, an ancient orc returned from Azeroth, Jorin chose to send an envoy to him before an army, to ask that the ogres be pulled back.', 'quest 10107 description (Kilrath sends news, the Boulderfist leader is an orc, convince him to pull back)'),
(351825, 1, 0, 255, 'He will not go home. Saurfang believes his destiny lies elsewhere, that he will serve a greater purpose someday, and he sent word to Farseer Corhuk that he must walk the earth. Corhuk only nodded and wiped away a tear. The son is the father, he said, and may the spirits have mercy on those who stand in his way.', 'quest 9866 description and reward text (destiny elsewhere, greater purpose, walk the earth; the son is the father)'),
(351825, 2, 13, 255, 'His road did lead elsewhere. In time Saurfang the Younger went to Azeroth to join his father, Varok Saurfang, in the Horde, and when the Horde sailed to war against the Lich King he followed it to Northrend.', 'creature 25257 Saurfang the Younger spawned on map 571 at the Kor''kron Vanguard (area 4170, Dragonblight); warcraft.wiki.gg/wiki/Dranosh_Saurfang (son of Varok, later traveled to Azeroth and reunited with his father)'),
(351826, 1, 0, 255, 'He knows his enemies personally. The Murkblood invasion plans that reached him were in a hand he knew: Ortor, a Broken who was once noble and wise in the ways of the elements and is now a muck addled lackey of Musel''ek the bog lord, and Arechron cursed him for a traitor.', 'quest 9871 reward text (Ortor, treacherous); quest 9873 description (once a noble Broken, versed in the elements, yes-man of Musel''ek)'),
(351826, 2, 0, 255, 'He also guards a secret. The Murkblood have been seizing and torturing Kurenai for word of the totem of Kar''dash, and Arechron admits that he knows of it, but there is much more to the story than he may tell. Only the chosen may learn it.', 'quest 9879 description and reward text (Kurenai tortured for word of the totem; only the chosen may be privy)'),
(351826, 3, 0, 255, 'Corki did not learn. After his rescue from the Burning Blade Ruins he ran off to the Boulderfist mounds of the Halaani Basin and was caught again, and then the Warmaul seized him and threatened to cook him in a stew. After the third rescue, Arechron sent the boy away to live among the night elves of Blade''s Edge, in the hope that they could keep him out of trouble.', 'quests 9924, 9954 descriptions (missing again, Warmaul ransom letter); creature_text 18440 (put in da Corki); creature_text 18445 (saved three times); quest 9955 reward text (sent to live among the night elves in Blade''s Edge)'),
(351827, 1, 0, 255, 'He is not wholly an orc. Lantresor is a blademaster of half orc and half draenei descent, one of a rare breed nearly all killed decades ago. He crossed the Dark Portal with the Horde in the days of the first invasions, served under two Warchiefs and returned to Draenor, and now he rules the Boulderfist. Pressed by the Warmaul and harried by orcs and Kurenai alike, he offered the envoy who came to him a bargain: help him turn his enemies against one another, and his ogres would leave their people in peace.', 'npc_text 9363, 9364 (half-orc descent, the other half draenei, a rare breed mostly killed decades ago); npc_text 9365 (served under the banner of two Warchiefs, now I rule Boulderfist); npc_text 9368, 9369 (another way, the plan; Boulderfist territory back, peace); smart_scripts 18261 (the gossip chain gives the 10107/10108 credit); quests 10107/10108 descriptions (ancient orc who passed through the Dark Portal in the time of our fathers, returned)'),
(351829, 1, 0, 255, 'Oshu''gun is his ancient vessel, the ship that first brought the draenei to this world. It fell from the heavens and crashed here many hundreds of years ago, and his weakened energies have been trapped in the wreckage ever since. He admits that he is the source of the ancestors'' pain.', 'quest 10101 reward text (ancient vessel, ship that first brought the draenei, crashed many hundreds of years ago, source of the orc spirits'' pain)'),
(351829, 2, 0, 255, 'As his Light bled away over the centuries, a void grew in its place and began to devour the souls of those nearby, and generations of orc spirits have been drawn helplessly into it. Worse, the Burning Legion has learned to harness the vortex and draw void creatures into its armies. K''ure believes the key to ending the cycle lies with another naaru, A''dal of Shattrath.', 'quest 10102 description (energies bled away, void growing, devouring souls, Legion harnessed the vortex, key lies with A''dal)'),
(351830, 1, 0, 255, 'In Garadar his rise is told as a rumor. The ogres of the hills once served the gronn, until Cho''war drove the gronn out of their cave on Warmaul Hill, declared himself king and dissolved the clans that had served under them. From those pieces the Warmaul were born. It was his ogres who ambushed a Mag''har funeral procession, and the Mag''har want his head.', 'quest 9946 description (ogre king, rumor, forced the gronn out of the cave, dissolved the clans, Warmaul born, deep in the caves); quest 9945 description (ambush on the procession)'),
(351830, 2, 0, 255, 'In Telaar he is known as Corki''s captor. When the Warmaul seized Arechron''s son and threatened to eat him, the boy learned from his cage that the key was carried by their king, Cho''war, the ogre who forced out the gronn that once ruled these ogres.', 'quest 9954 reward text (the Warmaul king, Cho''war, has the key); quest 9955 description (forced out the gronn that used to rule over these ogres, lives in the big cave)'),
(351831, 1, 0, 255, 'Both Garadar and Telaar have put a price on his head, the last and greatest of the bounties their wardens offer, for none has yet been able to rid Nagrand of him. Those who take up the hunt are urged to gather their allies before they go.', 'quests 9937/9938 descriptions (lords over the area around Oshu''gun, decimating all, none able to rid Nagrand of him, gather allies); quest_template_addon 9935/9939 and 9936/9940 (NextQuestID 9937/9938: offered only after both earlier bounties); creature_queststarter 9937 Warden Bullrok 18407, 9938 Warden Moi''bff Jill 18408'),
(351832, 1, 0, 255, 'The raiders are planning more than raids. Crudely painted maps of Nagrand carried by the Murkblood bear a big red mark where a town should be, and those who find them carry the plans home in haste: the Broken are preparing an attack.', 'quests 9871, 9872 descriptions (crudely painted map, big red X over Telaar or Garadar, planning an attack)'),
(351832, 2, 0, 255, 'The farseer got his wish. The raiders'' leader, Ortor of Murkblood, was slain among the huts of Sunspring, and his head was set upon a pike outside the gates of Garadar, a warning to any who would think to attack the town again.', 'quest 9867 reward text (the face of our enemy, a pike outside Garadar near the gates)'),
(351832, 3, 0, 255, 'The hand behind the plans was one Arechron knew: Ortor of Murkblood, once his friend and a noble Broken versed in the ways of the elements, now a muck addled servant of the bog lord Musel''ek. Ortor fell at Sunspring, but Arechron wonders what could have driven the Murkblood to so audacious an advance into orc lands. There is more to this, he says, than meets the eye.', 'quest 9871 reward text (Ortor, treacherous); quest 9873 description and reward text (someone I once knew, noble Broken, yes-man of Musel''ek; audacious advance, there is more to this)'),
(351832, 4, 0, 255, 'Captives freed at Sunspring revealed what the raiders truly seek, and why they have been seizing prisoners from the towns and tormenting them for answers: the lost totem of Kar''dash. What the totem is, and why Broken would want an orcish relic, none of the captives could say.', 'quest 9868 description (kidnapped in a raid on Garadar, seek to recover the totem of Kar''dash); quest 9879 description (murdered Kurenai in search of a lost relic, the totem of Kar''dash, an orcish implement)'),
(351833, 1, 0, 255, 'Of the thirty who set out, only two elders were found alive, Yorley and Ungriz. Warmaul ogres had fallen on the procession from all sides, slaughtering guards and mourners and desecrating the remains of the elder they were carrying, purely to show their power. Even the gentle Yorley, a spiritual orc, wanted vengeance on Warmaul Hill.', 'quest 9944 reward text (thirty orcs, only Ungriz and I remain); quest 9945 description (ambush, desecrated remains, spiritual orc''s limits, Warmaul Hill)'),
(351833, 2, 0, 255, 'Killing the attackers was only a start: their leader had to be dealt with. Their king, Cho''war the Pillager, was slain in the depths of his cave, and his head was posted at the gates of Garadar, so that the ogres would think twice before interrupting sacred Mag''hari rites again.', 'quest 9945 reward text (their leader must be dealt with); quest 9946 description and reward text (Cho''war, head posted at the gates, sacred Mag''hari rituals)'),
(351833, 3, 0, 255, 'Elder Ungriz, knowing that ogres like their food fresh, guessed that the Warmaul were keeping their Mag''har captives alive in cages on the hill. Keys were taken from the ogres, the cages opened, and the missing brothers and sisters of Garadar were brought home alive.', 'quest 9948 description and reward text (food fresh, keys on the ogres, brought back our missing brothers and sisters)'),
(351834, 1, 0, 255, 'On Kilrath''s plan the fat ogre, Unkor, was beaten until he talked. A new clan, the Warmaul, was driving the Boulderfist from their lands and killing their people; the Boulderfist chieftain, Krol, had vanished, and one Lantresor of the Blade ruled in his place. Jorin was far from pleased to hear that his village had been destroyed because the ogres needed more space.', 'quests 9889, 9890 (Kilrath''s plan, Unkor submits, Warmaul, Krol missing, Lantresor rules); quest 9891 description and reward text (village destroyed because the ogres needed more space)'),
(351834, 2, 0, 255, 'Bintook could barely read the ogres'' plans, but the lieutenant who wrote them, an ogre named Lump, proved easier to understand once he had been persuaded. The Warmaul had kicked the Boulderfist out of their mounds to the north, and with so many more mouths to feed, the hungry ogres had come looking for food, little Broken included.', 'quests 9917, 9918 (atrocious penmanship, Dump or Lump); npc_text 9354, 9355 (Lump: Warmaul kick Boulderfist out of mound to north, need food, eat da little ones)'),
(351834, 3, 0, 255, 'After both towns had struck at the ruins and the clefts, news came of the Boulderfist leader: he is an orc, an ancient blademaster who passed through the Dark Portal in the time of the Mag''har''s fathers and has since come home. An envoy was sent to Lantresor himself, to ask him to pull his ogres back.', 'quests 9906, 9907, 9921, 9922 (Burning Blade Ruins, twin clefts); quests 10107, 10108 descriptions (Diplomatic Measures)'),
(351834, 4, 0, 255, 'The old blademaster proposed a bargain instead. Warmaul banners were driven into slain Kil''sorrow orcs and Kil''sorrow banners into slain Warmaul ogres, and Kil''sorrow bodies were heaped in the Laughing Skull Courtyard at a smoke signal. With his two enemies at each other''s throats, Lantresor sent a peace offering home with the envoy: his clan had been saved from extermination, and the Boulderfist would accept peace.', 'quests 9927, 9928, 9931, 9932 (banners and bodies, smoke signal); quests 9933, 9934 descriptions (offering, saved my clan from extermination, accept the offering of peace)'),
(351834, 5, 0, 255, 'In Telaar the news was welcome. Arechron heard of the peace with something close to disbelief, then opened the Boulderfist offering and bade the envoy take whatever they desired from it, since without their efforts the peace would never have come about.', 'quest 9933 completion and reward text (Peace you say? take from the peace offering whatever you desire)'),
(351834, 6, 0, 255, 'In Garadar the offering found no welcome. Garrosh was unmoved by it. He kicked the crate aside and told the envoy to take whatever they desired from it, for neither he nor Garadar had any need of such useless trinkets.', 'quest 9934 completion and reward text (unmoved, kicks the crate aside, useless trinkets)'),
(351835, 1, 0, 255, 'Gordawg chewed the crushers'' cores and spat them out, pelting the stranger with rubble. Poison, he said. These rocks are not of Nagrand; they come from poison, and destroying the poison rock would lead to the usurper behind it.', 'quest 9821 description and reward text (chews rock, poison, these rocks are not Nagrand, you find usurper)'),
(351835, 2, 0, 255, 'With a boulder broken from Gordawg''s own back, the stranger went to the southwestern edge of the world, shattered the shells of the usurper''s minions and brought back a name: Gurok, an earth spirit who had betrayed the elements.', 'quest 9849 description and reward text (boulder from his back, edge of the world southwest, Gurok betrayed the elements)'),
(351835, 3, 0, 255, 'The Warmaul ogres worship Gurok at an earthen brand on Warmaul Hill. Seven ogre skulls laid upon it drew him out to be destroyed, and Gordawg crushed his earthen head between his jaws. Gurok''s reign was ended, the earthen elements were free, and the spirits of the earth could sleep.', 'quest 9853 description and reward text (Warmaul worship Gurok, seven skulls, earthen brand, Gordawg crushes head, reign has come to an end)'),
(351836, 1, 0, 255, 'The source proved to be the Lost Ones of Windyreed Village, who mean to spread their filth beyond the swamps of Zangarmarsh. With the blessing of the furies, Lo''ap handed over living fire plucked from the fiery essence of Incineratus himself, to be unleashed upon the village''s huts.', 'quest 9805 description (Lost Ones of Windyreed, living fire of Incineratus)'),
(351836, 2, 0, 255, 'The burning stifled the spread of the pollution, and Lo''ap confessed with shame that the culprits were his own kin, but more trouble surfaced. In shedding its corruption, Watoosun had cast off a twisted essence of the vilest filth, which now lurked in the depths of Lake Sunspring, breeding foul offspring.', 'quest 9805 completion and reward text (my own kin, stifled the spread, other troubles); quest 9810 description (Watoosun''s polluted essence in Lake Sunspring, corrupt offspring)'),
(351836, 3, 0, 255, 'The polluted essence was hunted down beneath the lake and destroyed along with its corrupt offspring. The elements sang of the victory the moment it fell, and the Earthen Ring gave its thanks.', 'quest 9810 reward text (the elements sang of your victory)'),
(351837, 1, 0, 255, 'The road to the champion was long. After Brokentoe came the Murkblood twins known as the Blue Brothers, then Rokdar the Sundered Lord, a giant hard as rock hauled from Blade''s Edge, then Skra''gath, a creature of air and shadow. The Warmaul champion himself had to be shipped in from the gladiator pits of Blade''s Edge, where he trained against mountain giants three at a time.', 'quests 9967, 9970, 9972, 9973 descriptions; creature_text 18069 (Mogor: Skra''gath made of air and shadow); creature_text 18471 (Rokdar hailing from Blade''s Edge)'),
(351837, 2, 0, 255, 'When the champion fell, Mogor would not let it end there. For the first time in the Ring of Blood''s history, the hero of the Warmaul invoked his right of battle and stepped into the ring himself, and the challenger had no choice but to face him.', 'quest 9973 reward text (Mogor has invoked his right of battle); creature_text 18471 (first time Mogor exercised his right of battle)'),
(351838, 1, 0, 255, 'Slowing the camps'' engineers bought him time, but as long as the transporters stood nothing would last, and fel steel could not be destroyed by ordinary means. Altruis wanted the camps'' blueprints, stolen from their mo''arg master planner, and he sent them to an old acquaintance in the Lower City of Shattrath: Sal''salabim, a drunken mo''arg who had once been a Legion engineer.', 'quest 9999 description and reward text (transporters, buying time, no conventional means of destroying fel steel); quest 10001 description and reward text (master planner''s blueprints, acquaintance was a Legion engineer); quest 10004 description (Sal''salabim in the Lower City, at the bar)'),
(351838, 2, 0, 255, 'After some persuading, and a few debts collected, Sal''salabim laughed and gave his answer. The camps were his own design, and their warding towers blind a demon hunter''s eyes. Turn the camps'' own fel cannons around, he said. The catch was that only the pit lord overseers held the keys to turn them.', 'quests 10009, 10010 (debts, ''This Sal''salabim design'', towers, demon hunter no can see, turn the cannons, overseers have keys); quest 10011 description (kill the overseers, take their keys, turn and fire the fel cannons)'),
(351838, 3, 0, 255, 'The overseers fell, their keys were taken, and the fel cannons turned on the camps of Hate and Fear. The Legion''s advance in western Nagrand was halted, and Altruis rewarded those who had made the victory possible.', 'quest 10011 reward text (we are victorious, the Legion''s advances have been halted)'),
(351839, 1, 0, 255, 'The potion, Kashur later admitted, did nothing; a spirit can be seen only if it allows it, and the potion was a test of belief. The ancestors at the Grounds had risen in torment, and when the stranger visited the old villages of the ancestors, Sunspring, the Laughing Skull Ruins, Garadar and the Bleeding Hollow, no spirits were at home. All were drifting south.', 'quest 10081 description and reward text (potion has no real effect, a test); quests 10082, 10085 descriptions and 10085 reward text (agitated ancestors, villages visited, spirits moving south)'),
(351839, 2, 0, 255, 'Kashur sent the stranger on to Oshu''gun, where the naaru K''ure revealed the truth: the void growing in his failing vessel was swallowing orc souls. He advised the stranger to seek out another naaru, A''dal, in the city of Shattrath.', 'quest 10101 description and reward text (Oshu''gun, K''ure); quest 10102 description (void devouring souls, A''dal)'),
(351839, 3, 0, 255, 'A''dal sent the stranger into the Auchenai Crypts, where the spirit of another naaru, D''ore, explained that the cycle could not be stopped, only eased, for without the void the Light cannot exist. Using the crypt''s soul mirrors, the stranger freed the ancient spirits of Nagrand before the void could claim them, and Mother Kashur gave thanks beyond words.', 'quests 10167, 10168 (Auchenai Crypts, D''ore, cycle cannot be stopped, without the void the Light cannot exist, soul mirrors); quest 10168 reward text (Kashur: thankful beyond what words could convey)'),
(351840, 1, 0, 255, 'It did not work. Garrosh admitted that his people were proud, but asked what lay beyond another winter, offered to let the stranger lead the clan instead, and declared that he would never become the second Hellscream to damn the orcs. Too ashamed to face the Greatmother, he sent the stranger back to tell her.', 'quest 10171 reward text (another winter, lead the clan); quest 10172 description (second Hellscream, too ashamed to look into her eyes)'),
(351840, 2, 0, 255, 'In tears, Geyah sent the stranger across the Dark Portal to Orgrimmar with a message for the Warchief: his blood is here, on this shattered world, and his father''s legacy endures. Tell him everything, she said, and tell him that she awaits him here.', 'quest 10172 reward text (seek out your warchief, I await him here); quest 10175 description (his blood is here, his father''s legacy lives on, tell him everything)'),
(351840, 3, 0, 255, 'Thrall answered. He came to Garadar with the Doomhammer, and the Greatmother, her eyes failing, knew her grandson by the way he moved and gave him at last the name Durotan had meant for his son: Go''el. Learning how Grom had truly died, she begged Thrall to tell Garrosh as well, and when he had, Garrosh cast off the shame of his bloodline and took up his father''s name as chieftain of the Mag''har.', 'creature_text 18141 (my eyes are not as sharp, you move like my son, Go''el, will you tell Garrosh); creature_text 18063 (thought my bloodline cursed, redemption, Garrosh Hellscream son of Grom, chieftain of the Mag''har); creature_text 18489 (He carries the Doomhammer); smart_scripts 18141 (event on the 10212 turn-in)'),
(351841, 1, 0, 255, 'Those who master all three hunts may face the queen of Nagrand: Tusker, a giant elekk who stands on a great bluff above Oshu''gun, beside whom Bach''lor, Gutripper and Banthar are nothing. Hemet offers, only half in jest, to send a letter to the next of kin.', 'quest 9852 description (Tusker, queen, bluff overlooking Oshu''gun, Bach''lor, Gutripper and Banthar are nothing, letter to next of kin)');
